25	export function parseCostDateRange(query: Record<string, unknown>) {
26	  const fromRaw = query.from as string | undefined;
27	  const toRaw = query.to as string | undefined;
28	  const from = fromRaw ? new Date(fromRaw) : undefined;
29	  const to = toRaw ? new Date(toRaw) : undefined;
30	  if (from && isNaN(from.getTime())) throw badRequest("invalid 'from' date");
31	  if (to && isNaN(to.getTime())) throw badRequest("invalid 'to' date");
32	  return (from || to) ? { from, to } : undefined;
33	}
34	
35	export function parseCostLimit(query: Record<string, unknown>) {
36	  const raw = Array.isArray(query.limit) ? query.limit[0] : query.limit;
37	  if (raw == null || raw === "") return 100;
38	  const limit = typeof raw === "number" ? raw : Number.parseInt(String(raw), 10);
39	  if (!Number.isFinite(limit) || limit <= 0 || limit > 500) {
40	    throw badRequest("invalid 'limit' value");
41	  }
42	  return limit;
43	}
