45	export function costRoutes(
46	  db: Db,
47	  options: { pluginWorkerManager?: PluginWorkerManager } = {},
48	) {
49	  const router = Router();
50	  const heartbeat = heartbeatService(db, {
51	    pluginWorkerManager: options.pluginWorkerManager,
52	  });
53	  const budgetHooks = {
