62	  router.post("/companies/:companyId/cost-events", validate(createCostEventSchema), async (req, res) => {
63	    const companyId = req.params.companyId as string;
64	    assertCompanyAccess(req, companyId);
65	
66	    if (req.actor.type === "agent" && req.actor.agentId !== req.body.agentId) {
67	      res.status(403).json({ error: "Agent can only report its own costs" });
68	      return;
69	    }
70	
71	    const event = await costs.createEvent(companyId, {
72	      ...req.body,
73	      occurredAt: new Date(req.body.occurredAt),
74	    });
75	
76	    const actor = getActorInfo(req);
77	    await logActivity(db, {
78	      companyId,
79	      actorType: actor.actorType,
80	      actorId: actor.actorId,
81	      agentId: actor.agentId,
82	      action: "cost.reported",
83	      entityType: "cost_event",
84	      entityId: event.id,
85	      details: { costCents: event.costCents, model: event.model },
86	    });
87	
88	    res.status(201).json(event);
89	  });
90	
91	  router.post("/companies/:companyId/finance-events", validate(createFinanceEventSchema), async (req, res) => {
92	    const companyId = req.params.companyId as string;
93	    assertCompanyAccess(req, companyId);
94	    assertBoard(req);
95	
96	    const event = await finance.createEvent(companyId, {
97	      ...req.body,
98	      occurredAt: new Date(req.body.occurredAt),
99	    });
100	
