102	    await logActivity(db, {
103	      companyId,
104	      actorType: actor.actorType,
105	      actorId: actor.actorId,
106	      agentId: actor.agentId,
107	      action: "finance_event.reported",
108	      entityType: "finance_event",
109	      entityId: event.id,
110	      details: {
111	        amountCents: event.amountCents,
112	        biller: event.biller,
113	        eventKind: event.eventKind,
114	        direction: event.direction,
115	      },
116	    });
117	
118	    res.status(201).json(event);
119	  });
