256	  router.patch("/companies/:companyId/budgets", validate(updateBudgetSchema), async (req, res) => {
257	    assertBoard(req);
258	    const companyId = req.params.companyId as string;
259	    assertCompanyAccess(req, companyId);
260	    const company = await companies.update(companyId, { budgetMonthlyCents: req.body.budgetMonthlyCents });
261	    if (!company) {
262	      res.status(404).json({ error: "Company not found" });
263	      return;
264	    }
265	
266	    await logActivity(db, {
267	      companyId,
268	      actorType: "user",
269	      actorId: req.actor.userId ?? "board",
270	      action: "company.budget_updated",
271	      entityType: "company",
272	      entityId: companyId,
273	      details: { budgetMonthlyCents: req.body.budgetMonthlyCents },
274	    });
275	
276	    await budgets.upsertPolicy(
277	      companyId,
278	      {
279	        scopeType: "company",
280	        scopeId: companyId,
281	        amount: req.body.budgetMonthlyCents,
282	        windowKind: "calendar_month_utc",
283	      },
284	      req.actor.userId ?? "board",
285	    );
286	
287	    res.json(company);
288	  });
289	
290	  router.patch("/agents/:agentId/budgets", validate(updateBudgetSchema), async (req, res) => {
291	    const agentId = req.params.agentId as string;
292	    const agent = await agents.getById(agentId);
293	    if (!agent) {
294	      res.status(404).json({ error: "Agent not found" });
295	      return;
296	    }
297	
298	    assertCompanyAccess(req, agent.companyId);
299	    assertBoard(req);
300	
301	    const updated = await agents.update(agentId, { budgetMonthlyCents: req.body.budgetMonthlyCents });
302	    if (!updated) {
303	      res.status(404).json({ error: "Agent not found" });
304	      return;
305	    }
306	
307	    const actor = getActorInfo(req);
308	    await logActivity(db, {
309	      companyId: updated.companyId,
310	      actorType: actor.actorType,
311	      actorId: actor.actorId,
312	      agentId: actor.agentId,
313	      action: "agent.budget_updated",
314	      entityType: "agent",
315	      entityId: updated.id,
316	      details: { budgetMonthlyCents: updated.budgetMonthlyCents },
317	    });
318	
319	    await budgets.upsertPolicy(
320	      updated.companyId,
321	      {
322	        scopeType: "agent",
323	        scopeId: updated.id,
324	        amount: updated.budgetMonthlyCents,
325	        windowKind: "calendar_month_utc",
326	      },
327	      req.actor.type === "board" ? req.actor.userId ?? "board" : null,
328	    );
329	
330	    res.json(updated);
331	  });
332	
333	  return router;
334	}
